// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the wall clock.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The bucket holds up to Burst tokens and refills at Rate tokens per second.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	clock    Clock
	maxWait  time.Duration // 0 means unlimited
}

// New creates a Limiter with the given refill rate (tokens/sec) and burst
// (max tokens). rate and burst must be > 0.
func New(rate float64, burst int) (*Limiter, error) {
	return NewWithClock(rate, burst, realClock{})
}

// NewWithClock is New with an injectable Clock.
func NewWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	return &Limiter{
		tokens: float64(burst),
		last:   clock.Now(),
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time since last refill.
// Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	elapsed := now.Sub(l.last)
	if elapsed <= 0 {
		return
	}
	l.last = now
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
}

// AllowN reports whether n tokens may be consumed immediately.
// If yes, the tokens are consumed.
func (l *Limiter) AllowN(n int) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.advance(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed immediately.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}
